s("5", "STC-ISP下载前需要先进行的操作是？", ["上电复位单片机", "关闭串口", "拔掉USB线", "删除hex文件"], "A", "STC冷启动方式：先点击下载，再给单片机上电，通过检测上电信号触发下载。")
s("5", "Keil中针对STC89C52RC应选择的目标芯片是？", ["8052", "8051", "8031", "8032"], "A", "STC89C52RC兼容MCS-51指令集，在Keil中选择标准8052即可。")
s("5", "STC89C52RC的程序存储器（Flash）容量是？", ["8KB", "4KB", "16KB", "32KB"], "A", "STC89C52RC内部有8KB Flash程序存储器。")
s("5", "Keil C51中定义特殊功能寄存器的关键字是？", ["sfr", "register", "volatile", "port"], "A", "C51用sfr关键字定义特殊功能寄存器，如sfr P1=0x90。")
s("5", "STC-ISP中设置下载波特率时，常用值是？", ["115200", "9600", "4800", "1200"], "A", "STC下载波特率常用115200提高下载速度；通信波特率常用9600。")
m("5", "STC89C52RC开发所需的软件工具包括？", ["Keil C51", "STC-ISP", "Proteus仿真", "AutoCAD"], ["A","B"], "Keil C51用于编程编译，STC-ISP用于下载烧录，Proteus可选用于仿真。")
m("5", "Keil C51工程创建步骤包括？", ["选择目标器件", "添加源文件", "设置编译选项", "焊接PCB板"], ["A","B","C"], "创建工程需选器件、添加源文件、设置编译选项；焊接PCB不属于软件步骤。")
m("5", "PlatformIO支持STC开发的特性包括？", ["跨平台", "命令行和IDE", "库管理", "内置硬件仿真器"], ["A","B","C"], "PlatformIO跨平台、支持CLI和IDE、有库管理器；不内置硬件仿真器。")
m("5", "STC-ISP下载失败常见原因有？", ["串口号选错", "未上电复位", "USB线断开", "电脑内存不足"], ["A","B","C"], "串口号错误、未冷启动上电、USB线断开均导致下载失败；内存不足通常不影响。")
m("5", "Keil C51中常用的调试功能有？", ["断点设置", "单步执行", "变量观察", "示波器波形"], ["A","B","C"], "断点、单步、变量观察是软件调试功能；示波器是外部仪器。")
j("5", "STC89C52RC使用USB转TTL模块下载程序时，TXD接单片机的RXD，RXD接TXD。", True, "串口通信需交叉连接：模块TXD→单片机RXD，模块RXD→单片机TXD。")
j("5", "PlatformIO只能开发STM32，不支持8051单片机。", False, "PlatformIO通过Intel MCS-51框架支持8051/STC单片机开发。")
j("5", "STC-ISP下载程序前必须先给单片机供电，再点击下载按钮。", False, "STC采用冷启动检测：需先点击下载，再给单片机上电触发下载。")
j("5", "Keil C51编译时默认会生成HEX文件。", False, "需在工程Options的Output页中勾选Create HEX File才会生成.hex文件。")
t("5", "简述STC89C52RC单片机程序开发与下载的完整流程。", "1)在Keil C51中创建工程、选择8052器件；2)编写C源文件并添加到工程；3)在Output选项中勾选Create HEX File；4)编译生成.hex文件；5)打开STC-ISP，选择正确型号和串口号；6)点击下载，然后给单片机上电冷启动；7)下载完成后程序自动运行。", "完整流程涵盖编程、编译、下载、运行四个阶段。")
t("5", "简述PlatformIO相比Keil C51的优势。", "PlatformIO优势：1)跨平台(Windows/Linux/macOS)；2)集成在VS Code中，代码补全和调试体验更好；3)内置包/库管理器；4)支持多种框架和数百种开发板；5)支持命令行CI/CD集成；6)开源免费。但Keil C51对8051优化和兼容性更好。", "PlatformIO更现代化，Keil更专业于51。")
t("5", "STC-ISP下载失败时如何排查问题？", "排查步骤：1)检查串口号是否正确(设备管理器中确认)；2)检查USB转TTL模块驱动是否安装(如CH340驱动)；3)确认TXD/RXD接线是否交叉连接；4)确认是否采用冷启动方式(先点下载再上电)；5)检查晶振是否起振(用示波器测XTAL引脚)；6)尝试降低下载波特率；7)检查芯片型号是否选对。", "系统化排查从软件到硬件逐层检查。")

# ===== ch6: C51程序设计基础 =====
s("6", "C51中 unsigned char 类型占用的字节数是？", ["1字节", "2字节", "4字节", "8字节"], "A", "unsigned char占1字节(0~255)，是8051最常用的数据类型。")
s("6", "C51中定义可位寻址变量的关键字是？", ["bit", "sbit", "bool", "flag"], "B", "sbit用于定义特殊功能寄存器的某一位，bit用于定义普通位变量。")
s("6", "C51中 unsigned int 类型占用的字节数是？", ["2字节", "1字节", "4字节", "8字节"], "A", "C51中int为16位即2字节，与PC上C语言int为4字节不同。")
s("6", "C51中 sfr P1 = 0x90 的作用是？", ["定义P1口地址", "定义变量P1", "定义中断", "定义常量"], "A", "sfr关键字将P1映射到特殊功能寄存器地址0x90。")
s("6", "C51中定义中断服务函数使用的关键字是？", ["interrupt", "isr", "irq", "vector"], "A", "C51用interrupt关键字声明中断函数，如void timer0_isr() interrupt 1。")
s("6", "C51中 code 关键字的作用是？", ["将变量存储在程序存储器", "定义代码段", "编译指令", "调试标记"], "A", "code关键字将数据存储在Flash程序存储器而非RAM，节省RAM空间。")
s("6", "8051中 P1 = 0xFF 的作用是？", ["P1口全部输出高电平", "P1口全部输出低电平", "P1口输入", "P1口清零"], "A", "向端口写0xFF使所有引脚输出高电平。")
s("6", "C51中 P1 ^= 0x01 的作用是？", ["翻转P1.0位", "P1口取反", "P1口清零", "P1口置1"], "A", "^=是异或赋值，0x01对应P1.0，异或使该位翻转。")
s("6", "C51中 _nop_() 函数的作用是？", ["延时一个机器周期", "空操作不延时", "返回0", "复位CPU"], "A", "_nop_()来自intrins.h，执行一个空操作，占用一个机器周期。")
s("6", "C51中定义指针指向xdata区变量的写法是？", ["int xdata *p", "xdata int *p", "int *xdata p", "int *p xdata"], "A", "存储区修饰符放在*之前：int xdata *p表示p指向xdata区的int变量。")
m("6", "C51中常用的存储器修饰符有？", ["data", "idata", "xdata", "code"], ["A","B","C","D"], "data(直接寻址00-7FH)、idata(间接寻址00-FFH)、xdata(外部RAM)、code(程序存储器)。")
m("6", "C51支持的基本数据类型有？", ["unsigned char", "unsigned int", "float", "bit"], ["A","B","C","D"], "C51支持char/int/float/bit等多种类型，其中bit和sbit是51特有。")
m("6", "C51中while循环和for循环的共同特点是？", ["都可用于循环控制", "都支持break退出", "都支持continue", "都自带延时功能"], ["A","B","C"], "while和for都是循环结构，支持break和continue；延时需手动实现。")
m("6", "C51中数组可以存储在哪些区域？", ["data区", "idata区", "xdata区", "code区"], ["A","B","C","D"], "数组可存储在任何存储区，code区存储常量数组节省RAM。")
m("6", "C51中使用指针操作的注意事项有？", ["注意存储区类型", "注意指针大小", "避免野指针", "指针必须全局"], ["A","B","C"], "指针需匹配存储区类型，通用指针占3字节，需避免未初始化使用；不必全局。")
j("6", "C51中 int 类型与标准C中 int 类型的字节数相同。", False, "C51中int为2字节(16位)，标准C中int通常为4字节(32位)。")
j("6", "C51中使用 code 关键字定义的数组存储在RAM中。", False, "code关键字将数据存储在Flash程序存储器中，不占用RAM。")
j("6", "C51中 sfr 定义的寄存器可以按位操作。", False, "sfr定义整个寄存器，需用sbit定义可位寻址的位才能按位操作。")
j("6", "C51中断函数中调用其他函数时需要使用 using 关键字指定寄存器组。", True, "using关键字指定中断函数使用的寄存器组，避免与主程序寄存器冲突。")
t("6", "简述C51中 data、idata、xdata、code 四种存储区的区别。", "data：直接寻址内部RAM 00H-7FH，访问速度最快；idata：间接寻址内部RAM 00H-FFH，52子系列可用高128字节；xdata：外部RAM 0000H-FFFFH，访问速度慢但容量大；code：程序存储器，只读，存储常量和表格。", "四种存储区各有用途，按速度和容量权衡选择。")
t("6", "简述C51中断服务函数的编写格式和注意事项。", "格式：void 函数名() interrupt n [using m]，其中n为中断号(0=外部中断0,1=定时器0,2=外部中断1,3=定时器1,4=串口)，m为寄存器组号(0-3)。注意事项：1)不能有参数和返回值；2)尽量短小，避免调用耗时函数；3)需在对应IE寄存器中使能中断；4)中断标志需手动清除(部分)；5)using可避免寄存器压栈开销。", "中断函数格式严格，编写需注意效率。")
t("6", "C51中如何实现精确延时？举例说明。", "方法：1)使用_nop_()函数(intrins.h)，每个_nop_()延时1个机器周期；2)用for循环嵌套，需根据晶振频率和机器周期计算；3)使用定时器中断实现精确定时。例如12MHz晶振，1机器周期=1us，void delay_us(unsigned char us){while(us--)_nop_();}可延时约us微秒。更精确延时用定时器。", "精确延时有多种方法，定时器最精确。")

# ===== ch7: 并行I/O端口与LED/按键 =====
s("7", "MCS-51中作为通用I/O需外接上拉电阻的端口是？", ["P0", "P1", "P2", "P3"], "A", "P0是开漏输出，无内部上拉，作通用I/O需外接上拉电阻。")
s("7", "LED共阳极接法，点亮LED需要IO输出？", ["低电平", "高电平", "高阻态", "脉冲"], "A", "共阳极LED正极接VCC，IO输出低电平时电流流过LED点亮。")
s("7", "按键消抖通常采用的延时时间是？", ["5-20ms", "1ms", "100ms", "1s"], "A", "机械按键抖动时间约5-20ms，延时10-20ms后再次检测可消除抖动。")
s("7", "4x4矩阵键盘扫描需要的I/O引脚数是？", ["8根", "4根", "16根", "2根"], "A", "4x4矩阵键盘用4行4列共8根I/O线，可识别16个按键。")
s("7", "MCS-51的P1口是哪种类型的I/O口？", ["准双向口", "开漏输出口", "推挽输出口", "高阻输入口"], "A", "P1/P2/P3是准双向口，P0是开漏输出。")
s("7", "LED流水灯中，P1口输出0xFE表示？", ["第1个LED亮其余灭", "第1个LED灭其余亮", "全部LED亮", "全部LED灭"], "A", "0xFE=11111110B，最低位为0，若LED共阳极则第1个LED亮。")
s("7", "矩阵键盘行列扫描法中，先输出行扫描码后应？", ["读取列状态", "延时等待", "发送数据", "清除中断"], "A", "行列扫描法：行输出扫描码，读取列状态判断哪个按键按下。")
s("7", "按键释放检测的作用是？", ["防止重复触发", "加速响应", "节省电能", "消除噪声"], "A", "检测按键释放确保一次按下只触发一次，防止重复响应。")
s("7", "P0口作外部总线使用时，复用的是？", ["低8位地址和数据", "高8位地址和数据", "控制和数据", "地址和控制"], "A", "P0作外部总线时分时复用低8位地址(A0-A7)和数据(D0-D7)，由ALE锁存。")
s("7", "LED限流电阻的计算公式是？", ["R=(Vcc-Vf)/If", "R=Vcc*If", "R=Vf/If", "R=(Vcc+Vf)/If"], "A", "限流电阻=(电源电压-LED正向压降)/工作电流。")
m("7", "MCS-51的准双向口特点包括？", ["输出前先写1再读取", "有内部上拉", "可直接驱动LED", "支持开漏"], ["A","B","C"], "准双向口读输入前需先写1，有弱上拉，可驱动LED；不支持开漏。")
m("7", "按键消抖的方法有？", ["软件延时消抖", "硬件RC滤波", "施密特触发器", "加大电源功率"], ["A","B","C"], "软件延时、RC滤波、施密特触发器均可消抖；加大电源无关。")
m("7", "矩阵键盘的扫描方式有？", ["行列扫描法", "线反转法", "中断扫描法", "ADC采样法"], ["A","B","C"], "行列扫描和线反转是常用方法；中断扫描用按键触发中断；ADC法用于模拟键盘。")
m("7", "LED数码管动态显示的特点有？", ["利用视觉暂留", "逐位扫描显示", "节省I/O引脚", "亮度更高"], ["A","B","C"], "动态显示利用人眼视觉暂留逐位扫描，节省引脚；亮度实际上比静态低。")
m("7", "P0口作通用I/O时需要外接上拉的原因是？", ["P0是开漏输出", "无内部上拉电阻", "驱动能力不足", "输入阻抗太高"], ["A","B"], "P0是开漏输出且无内部上拉，作I/O时需外接上拉电阻；驱动能力足够。")
j("7", "MCS-51的P3口引脚P3.0还具有RXD的第二功能。", True, "P3口各引脚均有第二功能，P3.0=RXD，P3.1=TXD等。")
j("7", "LED共阴极接法中IO输出高电平可以点亮LED。", True, "共阴极LED负极接地，IO输出高电平驱动电流点亮LED。")
j("7", "矩阵键盘扫描时不需要按键消抖处理。", False, "矩阵键盘同样存在抖动，扫描后需软件消抖确认。")
j("7", "准双向口读取引脚状态前必须先向该口写1。", True, "准双向口读输入前写1使内部FET截止，确保读到正确外部信号。")
t("7", "简述LED共阳极和共阴极接法的区别及驱动方式。", "共阳极：所有LED正极接VCC，IO输出低电平点亮LED，灌电流驱动；共阴极：所有LED负极接GND，IO输出高电平点亮LED，拉电流驱动。共阳极常用因为单片机灌电流能力通常大于拉电流。限流电阻R=(Vcc-Vf)/If。", "两种接法驱动电平相反，需根据硬件选择。")
t("7", "简述矩阵键盘行列扫描法的工作原理。", "原理：4x4矩阵键盘有4行4列。扫描步骤：1)4行依次输出低电平(其余为高)，如0xFE,0xFD,0xFB,0xF7；2)每次输出后读取4列状态；3)若某列也为低，则对应行列交叉的按键被按下；4)软件延时10-20ms消抖后再次确认；5)根据行列号计算键值。优点：8个IO控制16个按键，节省引脚。", "行列扫描是矩阵键盘最常用的检测方法。")
t("7", "简述按键消抖的原理和实现方法。", "原理：机械按键在按下和释放时触点会产生5-20ms的弹性抖动，导致电平在0和1间快速跳变。消抖方法：1)软件延时法——检测到按下后延时10-20ms再次检测，两次一致才确认；2)硬件RC滤波——并联电容滤除高频抖动；3)施密特触发器——利用回差电压消除抖动。软件消抖最常用，不增加硬件成本。", "消抖确保按键每次只触发一次。")

# ===== ch8: 中断系统 =====
s("8", "MCS-51有几个中断源？", ["5个", "3个", "2个", "6个"], "A", "MCS-51有5个中断源：INT0、INT1、T0、T1、串口中断。")
s("8", "MCS-51中定时器0的中断号是？", ["1", "0", "2", "3"], "A", "中断号：0=INT0，1=T0，2=INT1，3=T1，4=串口。")
s("8", "MCS-51中断允许寄存器是？", ["IE", "IP", "TCON", "SCON"], "A", "IE(中断允许寄存器)控制各中断源的使能，EA为总中断允许位。")
s("8", "MCS-51中EA=1的作用是？", ["开总中断", "关总中断", "开定时器", "开串口"], "A", "EA是IE寄存器的最高位，EA=1开总中断，EA=0关所有中断。")
s("8", "MCS-51中断优先级寄存器是？", ["IP", "IE", "PSW", "PCON"], "A", "IP寄存器设置各中断源的优先级，1为高优先级，0为低优先级。")
s("8", "MCS-51默认中断优先级最高的是？", ["INT0(外部中断0)", "T0(定时器0)", "串口中断", "T1(定时器1)"], "A", "同优先级时查询顺序：INT0>T0>INT1>T1>串口，INT0默认最高。")
s("8", "外部中断0的引脚是？", ["P3.2", "P3.3", "P3.4", "P3.5"], "A", "INT0对应P3.2，INT1对应P3.3，T0对应P3.4，T1对应P3.5。")
s("8", "MCS-51中IT0=1表示外部中断0触发方式为？", ["下降沿触发", "低电平触发", "上升沿触发", "高电平触发"], "A", "IT0=1为边沿触发(下降沿)，IT0=0为电平触发(低电平)。")
s("8", "中断服务函数返回时使用的指令是？", ["RETI", "RET", "RETURN", "JMP"], "A", "中断返回用RETI指令，恢复PC并清除中断优先级状态；普通子程序用RET。")
s("8", "MCS-51中断响应的最短时间为？", ["3个机器周期", "1个机器周期", "6个机器周期", "12个机器周期"], "A", "中断响应需3-8个机器周期，最短3个机器周期(无同级或高级中断时)。")
m("8", "MCS-51的5个中断源包括？", ["外部中断0", "定时器0中断", "外部中断1", "串口中断"], ["A","B","C","D"], "5个中断源：INT0、T0、INT1、T1、串口，选项均正确。")
m("8", "IE寄存器中控制中断使能的位有？", ["EA(总允许)", "EX0(外部中断0)", "ET0(定时器0)", "ES(串口)"], ["A","B","C","D"], "IE含EA、ET1、EX1、ET0、EX0、ES等中断允许控制位。")
m("8", "设置外部中断0下降沿触发的步骤包括？", ["IT0=1", "EX0=1", "EA=1", "TR0=1"], ["A","B","C"], "需设置触发方式IT0=1，使能EX0=1，开总中断EA=1；TR0是定时器启动位。")
m("8", "MCS-51中断优先级规则有？", ["高优先级可打断低优先级", "同级不能互相打断", "低优先级可打断高优先级", "同优先级按查询顺序"], ["A","B","D"], "高可打断低，同级不互相打断，同优先级按INT0>T0>INT1>T1>串口顺序。")
m("8", "中断服务函数编写注意事项有？", ["不能有参数", "不能有返回值", "尽量短小", "需手动清除部分标志位"], ["A","B","C","D"], "中断函数无形参无返回值，应短小高效，部分中断标志(TI/RI)需手动清除。")
j("8", "MCS-51的中断嵌套只允许高优先级中断打断低优先级中断。", True, "MCS-51支持两级中断优先级，高优先级可打断低优先级，同级不可嵌套。")
j("8", "中断服务函数中可以调用printf函数进行调试输出。", False, "中断函数应短小高效，避免调用printf等耗时函数，影响实时性。")
j("8", "串口中断的TI和RI标志位需要软件手动清除。", True, "TI和RI不会被硬件自动清除，需在中断服务函数中软件清零。")
j("8", "MCS-51复位后所有中断都处于使能状态。", False, "复位后IE=00H，所有中断均被禁止，需软件使能。")
t("8", "简述MCS-51中断系统的结构和各中断源。", "MCS-51有5个中断源：1)外部中断0(INT0,P3.2)；2)定时器0中断(T0)；3)外部中断1(INT1,P3.3)；4)定时器1中断(T1)；5)串口中断(RI/TI)。中断管理寄存器：IE控制使能，IP控制优先级，TCON控制外部中断触发方式和定时器，SCON控制串口中断标志。支持两级优先级，可实现嵌套。", "5个中断源各有用途，通过IE和IP管理。")
t("8", "简述外部中断的两种触发方式及选择原则。", "电平触发(IT0/IT1=0)：低电平有效，中断期间需保持低电平，中断返回前必须撤除低电平否则会重复触发，适合电平信号检测。边沿触发(IT0/IT1=1)：下降沿有效，硬件自动锁存中断请求，不会重复触发，适合脉冲信号。实际应用中边沿触发更常用，因为不易造成中断重复响应。", "边沿触发更常用，适合按键等场景。")
t("8", "编写外部中断0初始化和中断服务函数的C51代码框架。", "初始化：IT0=1; //下降沿触发; EX0=1; //使能外部中断0; EA=1; //开总中断。中断函数：void int0_isr() interrupt 0 { //中断处理代码; //边沿触发无需手动清标志; }。注意：中断号0对应INT0，函数不能有参数和返回值。", "中断编程三步：设触发方式、使能中断、开总中断。")
